313: async fn write_and_drain(
314:     shell: &mut SshShell,
315:     session: &SshSession,
316:     protocol: &mut Protocol,
317:     write: ShellWrite<'_>,
318:     output: &SyncSender<SessionEvent>,
319:     cancelled: &AtomicBool,
320:     lifecycle: &watch::Sender<TransportState>,
321: ) -> Result<WriteOutcome, String> {
322:     let (ShellWrite::Ordinary(bytes) | ShellWrite::Protocol(bytes)) = write;
323:     let writer = shell.writer();
324:     let writing = async {
325:         match write {
326:             ShellWrite::Ordinary(_) => writer.write(bytes).await,
327:             ShellWrite::Protocol(_) => writer.write_confirmed(bytes).await,
328:         }
329:     };
330:     let mut completion = shell.subscribe_completion();
331:     tokio::pin!(writing);
332:     loop {
333:         tokio::select! {
334:             biased;
335:             _ = cancellation(cancelled) => return Ok(WriteOutcome::Stopped),
336:             reason = shell_end(&mut completion) => {
337:                 lifecycle.send_replace(TransportState::Ended(reason));
338:                 return Ok(WriteOutcome::ShellEnded);
339:             },
340:             result = &mut writing => {
341:                 if let Some(reason) = shell.completion() {
342:                     lifecycle.send_replace(TransportState::Ended(reason));
343:                     return Ok(WriteOutcome::ShellEnded);
344:                 }
345:                 return result.map(|()| WriteOutcome::Written).map_err(|error| error.to_string());
346:             },
347:             _ = tokio::time::sleep(Duration::from_millis(4)) => {
348:                 if drain_output(shell, session, protocol, output).await? {
349:                     return Ok(WriteOutcome::Stopped);
350:                 }
351:                 if matches!(write, ShellWrite::Ordinary(_)) && protocol.input_blocked() {
352:                     // A remote peer can begin Zmodem while SSH flow control
353:                     // suspends an already admitted ordinary write. Stop polling
354:                     // that future at the ownership boundary: its unknown prefix
355:                     // cannot be replayed or mixed with protocol negotiation.
356:                     protocol.interrupt_ordinary_write();
357:                     return Err("SSH_ZMODEM_INPUT_HANDOFF_INTERRUPTED".into());
358:                 }
359:             }

