792:     fn cancel_wire(&mut self, output: &mut ZmodemOutput) {
793:         if let Some(stop) = &self.operation_stop {
794:             stop.store(true, Ordering::Release);
795:         }
796:         if let Some(machine) = &mut self.machine {
797:             match machine.cancel() {
798:                 Ok(events) => {
799:                     for event in events {
800:                         match event {
801:                             Event::Send(bytes) => output.writes.push(bytes),
802:                             Event::Terminal(bytes) => output.terminal.extend(bytes),
803:                             _ => {}
804:                         }
805:                     }
806:                 }
807:                 Err(_) => output.writes.push(CANCELLATION.to_vec()),
808:             }

